#!/bin/bash
# AIオフィス インストーラ（Mac）— ターミナルに1行貼って動かす。中身（キット）はこのファイルの末尾に入っている
# ブラウザで落としたファイルは macOS が止めるので、この形（curl で取って bash で動かす）にしている
set -u
KIT="$HOME/ai-office-kit"
echo "=== AIオフィス インストール ==="
rm -rf "$KIT" "$HOME/.ai-office-kit.tmp"; mkdir -p "$HOME/.ai-office-kit.tmp"
awk '/^__PAYLOAD_BELOW__$/{f=1;next} f' "$0" | base64 -D > "$HOME/.ai-office-kit.tmp/kit.zip" || { echo "✗ 取り出しに失敗"; exit 1; }
unzip -q "$HOME/.ai-office-kit.tmp/kit.zip" -d "$HOME/.ai-office-kit.tmp" && mv "$HOME/.ai-office-kit.tmp/ai-office-kit" "$KIT" && rm -rf "$HOME/.ai-office-kit.tmp"
chmod +x "$KIT"/*.command "$KIT"/AIオフィス/*.command "$KIT"/skill/discord-ai-office/scripts/*.sh 2>/dev/null
xattr -dr com.apple.quarantine "$KIT" 2>/dev/null
echo "✓ キットを $KIT に置きました"
echo ""
echo "設定シートを開きます。サーバー名・bot の名前・社員名簿などを書き換えて保存（⌘S）してください。"
echo "そのままで良ければ何もしなくてOK。"
open -e "$KIT/設定シート.txt"
read -r -p "書き終わったら（またはそのままで）このターミナルに戻って Enter: " _
exec bash "$KIT/skill/discord-ai-office/scripts/setup_mac.sh" "$KIT"   # stdin はターミナルのまま（/dev/tty を付けると claude auth login が kqueue EINVAL で落ちる）
exit 0
__PAYLOAD_BELOW__
__PAYLOAD_BELOW__

